    badRequest(response, "occurredAt must be a UTC timestamp formatted as YYYY-MM-DDTHH:mm:ss.SSSZ");
    return;
  }
  const lastEvent = scenario.events[scenario.events.length - 1];
  if (lastEvent !== undefined && parsed.getTime() < Date.parse(lastEvent.occurredAt)) {
    badRequest(response, "occurredAt must not be earlier than the last event's occurredAt");
    return;
  }
  occurredAt = body.occurredAt;
}

